// PR c++/115231
// { dg-additional-options "-fmodules-ts -Wno-global-module" }
// { dg-module-cmi M }

module;

template <typename T>
struct A {
  template <typename U> A(U);
};
template <typename T> A(T) -> A<T>;

export module M;

template <typename T>
struct B {
  template <typename U> B(U);
};
B(int) -> B<int>;

// Accessing deduction guides should be possible,
// even if we can't name the type directly.
export A<void> f();
export B<void> g();

// { dg-additional-options "-fmodules-ts" }
// { dg-module-cmi A }

export module A;

extern "C++" {
  template <typename T> struct S;
  S(int) -> S<int>;
  S(double) -> S<double>;
}

// { dg-additional-options "-fmodules-ts" }
// Test merging deduction guides.

template <typename T> struct S {
  template <typename U> S(U);
};

import A;
import B;
import C;

int main() {
  // declared in A and B
  S x(123);
  S<int> x2 = x;

  // declared only in A
  S y(0.5);
  S<double> y2 = y;

  // declared only in B
  S z('c');
  S<char> z2 = z;

  // declared only in C (and attached to named module)
  S w("hello");
  S<const char*> w2 = w;
}

S(char) -> S<double>;  // { dg-error "ambiguating" }

// { dg-additional-options "-fmodules-ts" }
// { dg-module-cmi B }

export module B;

extern "C++" {
  template <typename T> struct S;
  S(int) -> S<int>;
  S(char) -> S<char>;
}

// PR c++/115231
// { dg-additional-options "-fmodules-ts -Wno-global-module" }
// { dg-module-cmi M }

module;

template <typename T>
struct A {
  template <typename U> A(U);
};

template <typename T> A(T) -> A<T>;

export module M;

// Exporting a GMF entity should make the deduction guides reachable.
export using ::A;


export template <typename T>
struct B {
  template <typename U> B(U);
};

// Not exported, but should still be reachable by [temp.deduct.guide] p1.
B(int) -> B<double>;


// Class-scope deduction guides should be reachable as well, even if
// the class body was not exported.
export template <typename T> struct C;

template <typename T>
struct C {
  template <typename U>
  struct I {
    template <typename V> I(V);
  };

  I(int) -> I<int>;

  template <typename P>
  I(const P*) -> I<P>;
};

// PR c++/115231
// { dg-additional-options "-fmodules-ts" }

import M;

template <typename>
struct U;

template <template <typename> typename TT, typename Inner>
struct U<TT<Inner>> {
  void go() {
    TT t(10);
  }
};

int main() {
  U<decltype(f())>{}.go();
  U<decltype(g())>{}.go();
}

// { dg-additional-options "-fmodules-ts -Wno-global-module" }

module;
template <typename T> struct S;
export module C;
S(const char*) -> S<const char*>;

// PR c++/115231
// { dg-additional-options "-fmodules-ts" }

import M;

int main() {
  // Check that deduction guides are reachable,
  // and that they declared the right type.
  A a(1);
  A<int> a2 = a;

  B b(2);
  B<double> b2 = b;

  C<int>::I x(10);
  C<int>::I<int> x2 = x;

  C<int>::I y("xyz");
  C<int>::I<char> y2 = y;
}
